      "spec apiKey header 'X-Internal-Key' must be on the strip-list")
  }

  // MARK: - noRedirect returns the 3xx as-is (Gap 3.2)

  /// noRedirect=true MUST NOT follow the redirect; the 307 is returned to
  /// the caller verbatim rather than replaying the request body to the
  /// Location target. The token manager inspects/rejects the 3xx itself.
  @Test func testNoRedirectReturns307() async throws {
    let client = makeClient { _ in
      (self.body("moved"), 307, ["Location": "https://other.example/x"])
    }
    let resp = try await client.sendRequest(
      method: "POST", url: "https://auth.example.com/token",
      headers: [:], body: Data("grant_type=client_credentials".utf8), noRedirect: true)
    #expect(resp.statusCode == 307)
    #expect(resp.headers["location"] == "https://other.example/x")
  }

  /// 308 (Permanent Redirect) is likewise returned verbatim under
  /// noRedirect rather than followed.
  @Test func testNoRedirectReturns308() async throws {
    let client = makeClient { _ in
      (self.body("moved permanently"), 308, ["Location": "https://other.example/x"])
    }
    let resp = try await client.sendRequest(
      method: "POST", url: "https://auth.example.com/token",
      headers: [:], body: Data("grant_type=client_credentials".utf8), noRedirect: true)
    #expect(resp.statusCode == 308)
  }

  /// When noRedirect is omitted the request-options-free overload routes
  /// through the regular session and a 200 response is surfaced
  /// untouched -- the OAuth2 path opts in, but BaseApi requests
  /// must not regress.
  @Test func testNoRedirectFalseAllowsNormalRequest() async throws {
    let client = makeClient { _ in (self.body("ok"), 200, [:]) }
    let resp = try await client.sendRequest(
      method: "GET", url: "http://localhost/echo",
      headers: [:], body: nil)
    #expect(resp.statusCode == 200)
  }

  // MARK: - Content-Encoding lie (Gap AL)

  // content-encoding-lie-corrupt-passthrough (Gap AL): a server that
  // advertises `Content-Encoding: gzip` AND sends a body that BEGINS WITH the
  // gzip magic bytes (0x1F 0x8B) — so it both claims and looks like gzip — but
  // is not a decodable gzip stream must surface as the SDK's ApiError, never a
  // silent corrupt passthrough. The magic-byte prefix is what tells the client
  // the body was genuinely left encoded (rather than already decompressed by
  // URLSession, which on Linux leaves the Content-Encoding header in place); on
  // a real-gzip stream the client gunzips it, so the only way to reach the
  // error path deterministically is a malformed stream that still carries the
  // magic.
  @Test func testLyingGzipContentEncodingThrowsApiError() async throws {
    // gzip magic prefix (0x1F 0x8B) + garbage tail: declares gzip, looks
    // like gzip, but is not a valid gzip stream.
    var lyingBody = Data([0x1F, 0x8B])
    lyingBody.append(Data("this is not a valid gzip stream".utf8))
    let client = makeClient { _ in
      (
        lyingBody, 200,
        ["Content-Type": "application/json", "Content-Encoding": "gzip"]
      )
    }
    let error = await #expect(throws: ApiError.self) {
      _ = try await client.sendRequest(
        method: "GET", url: "http://localhost/bad-gzip", headers: [:], body: nil)
    }
    /* The response arrived, so the error carries its real status code and
       is never a NetworkError. */
    #expect(error?.statusCode == 200)
    #expect(!(error is NetworkError))
  }

  // A body URLSession itself cannot decode (it reports
  // URLError.cannotDecodeContentData after the response arrived) is likewise
  // an ApiError with the real status, never a NetworkError.
  @Test func testUndecodableBodyReportedByURLSessionThrowsApiErrorWithStatus() async throws {
    let client = makeClient { _ in
      (
        Data("ignored".utf8), 502,
        [
          "Content-Type": "application/json",
          UnitStubURLProtocol.failWithHeader: "cannotDecodeContentData",
        ]
      )
    }
    let error = await #expect(throws: ApiError.self) {
      _ = try await client.sendRequest(
        method: "GET", url: "http://localhost/undecodable", headers: [:], body: nil)
    }
    #expect(error?.statusCode == 502)
    #expect(!(error is NetworkError))
  }

  // A connection that is reset, or a deadline that passes, AFTER the response
  // headers arrived is still a transport failure: status 0 and the URLError
  // kept as the cause, never an ApiError carrying the 200 that was received.
  @Test func testBodyTruncatedAfterHeadersIsNetworkError() async throws {
    let client = makeClient { _ in
      (
        Data("partial body".utf8), 200,
        [
          "Content-Type": "application/json",
          UnitStubURLProtocol.failWithHeader: "networkConnectionLost",
        ]
      )
    }
    let error = await #expect(throws: NetworkError.self) {
      _ = try await client.sendRequest(
        method: "GET", url: "http://localhost/truncated", headers: [:], body: nil)
    }
    #expect(error?.statusCode == 0)
    #expect(!(error is NetworkTimeoutError))
    #expect((error?.underlyingError as? URLError)?.code == .networkConnectionLost)
  }

  @Test func testBodyStalledPastTheDeadlineAfterHeadersIsNetworkTimeoutError() async throws {
    let client = makeClient { _ in
      (
        Data("partial body".utf8), 200,
        ["Content-Type": "application/json", UnitStubURLProtocol.failWithHeader: "timedOut"]
      )
    }
    let error = await #expect(throws: NetworkTimeoutError.self) {
      _ = try await client.sendRequest(
        method: "GET", url: "http://localhost/stalled", headers: [:], body: nil)
    }
    #expect(error?.statusCode == 0)
    #expect((error?.underlyingError as? URLError)?.code == .timedOut)
  }

  // A malformed or non-HTTP request URL is a caller mistake:
  // ConfigurationError.invalidArgument, never a NetworkError.
  @Test(arguments: ["http://[::1", "file:///etc/passwd"])
  func testMalformedRequestUrlThrowsInvalidArgument(url: String) async throws {
    let client = makeClient { _ in (self.body(), 200, [:]) }
    let error = await #expect(throws: ConfigurationError.self) {
      _ = try await client.sendRequest(method: "GET", url: url, headers: [:], body: nil)
    }
    guard case .invalidArgument? = error else {
      Issue.record("expected ConfigurationError.invalidArgument, got \(String(describing: error))")
      return
    }
  }

  // content-encoding-residual-plaintext-passthrough (Gap AL regression): on
  // Linux swift-corelibs-foundation (libcurl) decompresses the body in place
  // but LEAVES the `Content-Encoding: gzip` header on the response. A body
  // that carries that residual header yet does NOT begin with the gzip magic
  // bytes has already been decompressed (or was always plaintext) and MUST be
  // passed through unchanged — never thrown on. A pure-plaintext body is
  // indistinguishable from an already-decompressed one, so it cannot be
  // treated as a lie. This pins the fix for the regression where the old guard
  // threw on every normal Linux response.
  @Test func testResidualGzipHeaderWithoutMagicPassesThrough() async throws {
    let client = makeClient { _ in
      // No gzip magic — plaintext JSON under a residual gzip header.
      (
        Data(#"{"ok":true}"#.utf8), 200,
        ["Content-Type": "application/json", "Content-Encoding": "gzip"]
      )
    }
    let resp = try await client.sendRequest(
      method: "GET", url: "http://localhost/residual-gzip", headers: [:], body: nil)
    #expect(resp.statusCode == 200)
    #expect(resp.body.contains("ok"))
  }

  // content-encoding-identity-passthrough (Gap AL): `Content-Encoding:
  // identity` is a no-op encoding (RFC 7231 §3.1.2.1) — the body is already
  // plaintext, so it must pass through unchanged, NOT be treated as a lie.
  @Test func testIdentityContentEncodingPassesThrough() async throws {
    let client = makeClient { _ in
      (
        Data(#"{"ok":true}"#.utf8), 200,
        ["Content-Type": "application/json", "Content-Encoding": "identity"]
      )
    }
    let resp = try await client.sendRequest(
      method: "GET", url: "http://localhost/identity", headers: [:], body: nil)
    #expect(resp.statusCode == 200)
    #expect(resp.body.contains("ok"))
  }

  // content-encoding-caller-managed (Gap AL): a caller who explicitly sets
  // `Accept-Encoding` has opted to receive and decode the encoded bytes
  // itself, so a residual `Content-Encoding` header is expected and must NOT
  // be treated as an error — the encoded body is returned to that caller.
  @Test func testCallerManagedAcceptEncodingDoesNotThrow() async throws {
    let client = makeClient { _ in
      (
        Data("caller-decodes-these-bytes".utf8), 200,
        ["Content-Type": "application/octet-stream", "Content-Encoding": "gzip"]
      )
    }
    let resp = try await client.sendRequest(
      method: "GET", url: "http://localhost/caller-gzip",
      headers: ["Accept-Encoding": "gzip"], body: nil)
    #expect(resp.statusCode == 200)
  }

  // content-encoding-empty-gzip-passthrough (Gap AL): a zero-byte body that
  // still advertises `Content-Encoding: gzip` has nothing to inflate and no
  // gzip magic, so it must pass through as an empty body — never be thrown on.
  @Test func testEmptyGzipBodyPassesThroughAsEmpty() async throws {
    let client = makeClient { _ in
      (
        Data(), 200,
        ["Content-Type": "application/json", "Content-Encoding": "gzip"]
      )
    }
    let resp = try await client.sendRequest(
      method: "GET", url: "http://localhost/empty-gzip", headers: [:], body: nil)
    #expect(resp.statusCode == 200)
    #expect(resp.body.isEmpty)
  }

  // MARK: - Redirect origin comparison

  /* Credentials are stripped on a redirect only when the origin changes, so
   * the comparison must treat an implicit and an explicit default port as
   * the same origin (https://h and https://h:443) and must not do so for
   * any other difference in scheme, host or port. */
  @Test func testSameOriginComparesSchemeHostAndEffectivePort() throws {
    let cases: [(String, String, Bool)] = [
      ("https://example.com/a", "https://example.com:443/b", true),
      ("https://example.com:443/a", "https://example.com/b", true),
      ("http://example.com/a", "http://example.com:80/b", true),
      ("https://EXAMPLE.com/a", "https://example.com/b", true),
      ("https://example.com:8443/a", "https://example.com:8443/b", true),
      ("https://example.com/a", "https://example.com:8443/b", false),
      ("https://example.com/a", "https://example.com:80/b", false),
      ("http://example.com/a", "http://example.com:443/b", false),
      ("https://example.com/a", "http://example.com/b", false),
      ("http://example.com:443/a", "https://example.com/b", false),
      ("https://example.com/a", "https://other.example.com/b", false),
    ]
    for (left, right, expected) in cases {
      let a = try #require(URL(string: left))
      let b = try #require(URL(string: right))
      #expect(
        DefaultApiClient.sameOrigin(a, b) == expected,
        "sameOrigin(\(left), \(right)) should be \(expected)")
    }
  }

  // MARK: - Accept-Encoding

  /* URLSession negotiates and decodes content encodings itself only while
   * the header is left unset, so the client must not advertise one of its
   * own. */
  @Test func testDoesNotSetAcceptEncodingByDefault() async throws {
    var capturedEncoding: String?
    let client = makeClient { req in
      capturedEncoding = req.value(forHTTPHeaderField: "Accept-Encoding")
      return (self.body(), 200, [:])
    }
    _ = try await client.sendRequest(
      method: "GET", url: "http://localhost/test", headers: [:], body: nil)
    #expect(capturedEncoding == nil)
  }

  // MARK: - Session configuration

  /* The production session keeps no cookies and no response cache, so two
     identical calls behave identically and one client never sees another's
     Set-Cookie. URLSessionConfiguration.default would do both. */
  @Test func testSessionIsStatelessWithoutCookiesOrCache() throws {
    let (session, _) = try DefaultApiClient.buildSession(TransportOptionsBuilder().build())
    let config = session.configuration
    #expect(config.httpCookieStorage == nil)
    #expect(config.httpShouldSetCookies == false)
    #expect(config.urlCache == nil)
    #expect(config.requestCachePolicy == .reloadIgnoringLocalCacheData)
  }

  /* noRedirect requests (OAuth2 token calls) share ONE long-lived session
     built from the primary configuration, rather than a fresh, never
     invalidated session per call that dropped the proxy and timeouts. */
  @Test func testNoRedirectSessionIsReusedAndInheritsThePrimaryConfiguration() {
    let config = URLSessionConfiguration.ephemeral
    config.httpShouldSetCookies = false
    config.requestCachePolicy = .reloadIgnoringLocalCacheData
    config.timeoutIntervalForRequest = 7
    let client = DefaultApiClient(transportOptions: nil, session: URLSession(configuration: config))
    let first = client.noRedirectSession()
    #expect(first === client.noRedirectSession())
    #expect(first.configuration.httpShouldSetCookies == false)
    #expect(first.configuration.requestCachePolicy == .reloadIgnoringLocalCacheData)
    #expect(first.configuration.timeoutIntervalForRequest == 7)
    client.close()
  }

  /* CFNetwork chooses the proxy by the TARGET scheme, so an http:// proxy
     must be wired for https:// targets too (and the reverse), or half the
     traffic bypasses it. */
  @Test func testProxyDictionaryCoversBothTargetSchemes() throws {
    let http = DefaultApiClient.proxyConnectionDictionary(
      try #require(URL(string: "http://proxy.example.com:3128")))
    #expect(http["HTTPEnable"] as? Bool == true)
    #expect(http["HTTPProxy"] as? String == "proxy.example.com")
    #expect(http["HTTPPort"] as? Int == 3128)
    #expect(http["HTTPSEnable"] as? Bool == true)
    #expect(http["HTTPSProxy"] as? String == "proxy.example.com")
    #expect(http["HTTPSPort"] as? Int == 3128)

    let https = DefaultApiClient.proxyConnectionDictionary(
      try #require(URL(string: "https://proxy.example.com")))
    #expect(https["HTTPEnable"] as? Bool == true)
    #expect(https["HTTPPort"] as? Int == 443)
    #expect(https["HTTPSEnable"] as? Bool == true)
    #expect(https["HTTPSPort"] as? Int == 443)

    let bare = DefaultApiClient.proxyConnectionDictionary(
      try #require(URL(string: "http://proxy.example.com")))
    #expect(bare["HTTPPort"] as? Int == 80)
    #expect(bare["HTTPSPort"] as? Int == 80)
  }

  // MARK: - Redirect body-replay guard

  /* Only a real body is refused across an HTTPS -> HTTP hop. The empty Data
     attached to a body-less POST/PUT/PATCH carries nothing to leak. */
  @Test func testBodyReplayGuardIgnoresEmptyBodies() throws {
    let url = try #require(URL(string: "http://other.example/x"))
    var withBody = URLRequest(url: url)
    withBody.httpBody = Data("secret".utf8)
    var empty = URLRequest(url: url)
    empty.httpBody = Data()
    let none = URLRequest(url: url)

    #expect(
      DefaultApiClient.refusesBodyReplay(
        currentScheme: "https", nextScheme: "http", request: withBody, originalBody: nil))
    #expect(
      !DefaultApiClient.refusesBodyReplay(
        currentScheme: "https", nextScheme: "http", request: empty, originalBody: nil))
    #expect(
      !DefaultApiClient.refusesBodyReplay(
        currentScheme: "https", nextScheme: "http", request: none, originalBody: nil))
    #expect(
      !DefaultApiClient.refusesBodyReplay(
        currentScheme: "http", nextScheme: "https", request: withBody, originalBody: nil))
    #expect(
      !DefaultApiClient.refusesBodyReplay(
        currentScheme: "http", nextScheme: "http", request: withBody, originalBody: nil))
  }

  /* URLSession may hand the redirect a body STREAM; an original empty body
     still means there is nothing to replay. */
  @Test func testBodyReplayGuardTreatsStreamOfEmptyOriginalAsEmpty() throws {
    var streamed = URLRequest(url: try #require(URL(string: "http://other.example/x")))
    streamed.httpBodyStream = InputStream(data: Data())
    #expect(
      !DefaultApiClient.refusesBodyReplay(
        currentScheme: "https", nextScheme: "http", request: streamed, originalBody: Data()))
    #expect(
      DefaultApiClient.refusesBodyReplay(
        currentScheme: "https", nextScheme: "http", request: streamed, originalBody: Data("x".utf8))
    )
    #expect(
      DefaultApiClient.refusesBodyReplay(
        currentScheme: "https", nextScheme: "http", request: streamed, originalBody: nil))
  }

  // MARK: - Bare utf-16 byte-order marks

  /* A bare utf-16 label honours a leading byte-order mark and drops it; the
     big-endian default only applies when there is none. */
  @Test func testBareUtf16LittleEndianBomDecodesLittleEndian() async throws {
    let client = makeClient { _ in
      (
        Data([0xFF, 0xFE, 0x41, 0x00, 0x42, 0x00]), 200,
        ["Content-Type": "text/plain; charset=utf-16"]
      )
    }
    let resp = try await client.sendRequest(
      method: "GET", url: "http://localhost/le", headers: [:], body: nil)
    #expect(resp.body == "AB", "got: \(resp.body.unicodeScalars.map { $0.value })")
  }

  @Test func testBareUtf16BigEndianBomIsDropped() async throws {
    let client = makeClient { _ in
      (
        Data([0xFE, 0xFF, 0x00, 0x41, 0x00, 0x42]), 200,
        ["Content-Type": "text/plain; charset=utf-16"]
      )
    }
    let resp = try await client.sendRequest(
      method: "GET", url: "http://localhost/be", headers: [:], body: nil)
    #expect(resp.body == "AB", "got: \(resp.body.unicodeScalars.map { $0.value })")
  }

  /* An explicit utf-16le label is not sniffed: it never second-guesses the
     declared byte order. */
  @Test func testExplicitUtf16LittleEndianLabelIsNotSniffed() {
    let text = DefaultApiClient.decodeText(
      Data([0x41, 0x00, 0x42, 0x00]), contentType: "text/plain; charset=utf-16le")
    #expect(text == "AB")
  }

  // MARK: - CA certificate files

  /* SecCertificateCreateWithData only takes DER, so PEM is unwrapped
     first, and a bundle yields every certificate in it. */
  @Test func testParseCaCertificatesReadsEveryPemBlock() {
    let pem = """
      header text
      -----BEGIN CERTIFICATE-----
      MAMC
      AQU=
      -----END CERTIFICATE-----
      -----BEGIN CERTIFICATE-----\r
      MAMCAQY=\r
      -----END CERTIFICATE-----
      """
    let certificates = DefaultApiClient.parseCaCertificates(Data(pem.utf8))
    #expect(
      certificates == [
        Data([0x30, 0x03, 0x02, 0x01, 0x05]), Data([0x30, 0x03, 0x02, 0x01, 0x06]),
      ])
  }

  @Test func testParseCaCertificatesAcceptsDerAndRejectsOtherBytes() {
    let der = Data([0x30, 0x03, 0x02, 0x01, 0x05])
    #expect(DefaultApiClient.parseCaCertificates(der) == [der])
    #expect(DefaultApiClient.parseCaCertificates(Data("not a certificate".utf8)).isEmpty)
    #expect(DefaultApiClient.parseCaCertificates(Data()).isEmpty)
    let armourOnly = "-----BEGIN CERTIFICATE-----\n!!!!\n-----END CERTIFICATE-----\n"
    #expect(DefaultApiClient.parseCaCertificates(Data(armourOnly.utf8)).isEmpty)
  }

  @Test func testUnparseableCaCertFileFailsFast() throws {
    let file = FileManager.default.temporaryDirectory
      .appendingPathComponent("garbage-\(UUID().uuidString).pem")
    try Data("not a certificate".utf8).write(to: file)
    defer { try? FileManager.default.removeItem(at: file) }
    let transport = TransportOptionsBuilder().caCertPath(file.path).build()
    #expect(
      throws: ConfigurationError.invalidCACertificate(
        "failed to parse \"\(file.path)\": no PEM blocks found or unparseable")
    ) {
      _ = try DefaultApiClient(transportOptions: transport)
    }
  }

  #if os(Linux)
    /* URLSession on Linux cannot apply either TLS override, so asking for one
       must fail loudly instead of being silently dropped. */
    @Test func testDisablingVerificationIsRefusedOnLinux() {
      let transport = TransportOptionsBuilder().verifySsl(false).build()
      #expect(throws: ConfigurationError.tlsOptionsUnsupported) {
        _ = try DefaultApiClient(transportOptions: transport)
      }
    }

    @Test func testCaCertificateIsRefusedOnLinux() throws {
      let file = FileManager.default.temporaryDirectory
        .appendingPathComponent("der-\(UUID().uuidString).der")
      try Data([0x30, 0x03, 0x02, 0x01, 0x05]).write(to: file)
      defer { try? FileManager.default.removeItem(at: file) }
      let transport = TransportOptionsBuilder().caCertPath(file.path).build()
      #expect(throws: ConfigurationError.tlsOptionsUnsupported) {
        _ = try DefaultApiClient(transportOptions: transport)
      }
    }
  #endif

  // MARK: - CA certificate fail-fast

  @Test func testNonexistentCaCertPathFailsFast() {
    // ca-cert-fail-fast: an explicitly configured CA certificate path that
    // cannot be read or parsed must fail fast at construction with
    // ConfigurationError rather than silently falling back to the system
    // trust store (security theater). It is a configuration mistake, not
    // an ApiError.
    let transport = TransportOptionsBuilder().caCertPath("/nonexistent/ca.pem").build()
    #expect(
      throws: ConfigurationError.invalidCACertificate("failed to read \"/nonexistent/ca.pem\"")
    ) {
      _ = try DefaultApiClient(transportOptions: transport)
    }
  }
}

// MARK: - Model-part stand-in for multipart unit tests

/// A Codable stand-in for a generated model used as a multipart part. Its
/// stored properties carry camelCase WIRE names, exactly as generated models
/// do, so the multipart model-part branch can be exercised without referring
/// to any model that happens to exist in the spec being generated.
private struct MultipartModelPartFixture: Codable {
  let isEnabled: Bool
  let recordedAt: Date
}

// MARK: - URL Protocol stub for unit tests

private final class UnitStubURLProtocol: URLProtocol {
  nonisolated(unsafe) static var handler: ((URLRequest) -> (Data, Int, [String: String]))?
  /// A response header naming a URLError code makes the stub fail the load
  /// with that error after the response is delivered.
  static let failWithHeader = "X-Stub-Fail-With"

  static func session(handler: @escaping (URLRequest) -> (Data, Int, [String: String]))
    -> URLSession
  {
    self.handler = handler
    let config = URLSessionConfiguration.ephemeral
    config.protocolClasses = [UnitStubURLProtocol.self]
    return URLSession(configuration: config)
  }

  override class func canInit(with request: URLRequest) -> Bool { return true }
  override class func canonicalRequest(for request: URLRequest) -> URLRequest { return request }

  /// URLSession hands a protocol the body as `httpBodyStream`, not
  /// `httpBody`; read it back so handlers can inspect what was sent.
  static func withBody(_ request: URLRequest) -> URLRequest {
    guard request.httpBody == nil, let stream = request.httpBodyStream else { return request }
    var copy = request
    var data = Data()
    stream.open()
    defer { stream.close() }
    let bufferSize = 4096
    let buffer = UnsafeMutablePointer<UInt8>.allocate(capacity: bufferSize)
    defer { buffer.deallocate() }
    while stream.hasBytesAvailable {
      let read = stream.read(buffer, maxLength: bufferSize)
      if read <= 0 { break }
      data.append(buffer, count: read)
    }
    copy.httpBody = data
    return copy
  }

  override func startLoading() {
    guard let handler = UnitStubURLProtocol.handler else {
      client?.urlProtocolDidFinishLoading(self)
      return
    }
    var (data, statusCode, headers) = handler(UnitStubURLProtocol.withBody(request))
    let failWith = headers.removeValue(forKey: UnitStubURLProtocol.failWithHeader)
    guard let requestURL = request.url,
      let response = HTTPURLResponse(
        url: requestURL,
        statusCode: statusCode,
        httpVersion: "HTTP/1.1",
        headerFields: headers
      )
    else {
      client?.urlProtocolDidFinishLoading(self)
      return
    }
    client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
    if failWith == "cannotDecodeContentData" {
      client?.urlProtocol(self, didFailWithError: URLError(.cannotDecodeContentData))
      return
    }
    /* The connection dies, or the deadline passes, after the response
     * headers and part of the body have already arrived. */
    if failWith == "networkConnectionLost" || failWith == "timedOut" {
      client?.urlProtocol(self, didLoad: data.prefix(1))
      let code: URLError.Code = failWith == "timedOut" ? .timedOut : .networkConnectionLost
      client?.urlProtocol(self, didFailWithError: URLError(code))
      return
    }
    client?.urlProtocol(self, didLoad: data)
    client?.urlProtocolDidFinishLoading(self)
  }

  override func stopLoading() {}
}
